/**
 * ZEGOCLOUD token minting.
 *
 * The server secret never reaches the browser, which is why this exists at all:
 * ZEGOCLOUD's client SDKs can be initialised with an app sign instead of a
 * token, and that requires shipping the secret to the page. Anyone who viewed
 * source could then mint tokens for any room in the project.
 *
 * ON THE TOKEN FORMAT
 *
 * This implements ZEGO's `token04` format — version byte, expiry, AES-GCM
 * ciphertext of a small JSON body — transcribed from their published
 * specification. It was written from the spec rather than generated by their
 * `zego-server-assistant` package, so **it must be proved against a live
 * ZEGOCLOUD project before launch**. If a real call fails to connect with a
 * token error, replace `generateToken04` here with the official package rather
 * than debugging this by hand:
 *
 *   npm install zego-server-assistant
 *
 * The signature of `mintSessionToken` is the only thing the rest of the
 * codebase depends on, so that swap is contained to this file.
 */

import 'server-only';
import { createCipheriv, randomBytes } from 'node:crypto';

/** 32 bytes exactly — AES-256 needs that, and a wrong length fails silently. */
const SECRET_LENGTH = 32;

export class VideoConfigError extends Error {
  constructor(message) {
    super(message);
    this.code = 'video_not_configured';
  }
}

export function videoConfig() {
  const appId = Number(process.env.ZEGOCLOUD_APP_ID);
  const secret = process.env.ZEGOCLOUD_SERVER_SECRET;

  if (!appId || Number.isNaN(appId)) {
    throw new VideoConfigError('ZEGOCLOUD_APP_ID is not set.');
  }
  if (!secret) {
    throw new VideoConfigError('ZEGOCLOUD_SERVER_SECRET is not set.');
  }
  if (secret.length !== SECRET_LENGTH) {
    throw new VideoConfigError(
      `ZEGOCLOUD_SERVER_SECRET must be exactly ${SECRET_LENGTH} characters ` +
        `(this one is ${secret.length}).`,
    );
  }
  if (process.env.NEXT_PUBLIC_ZEGOCLOUD_SERVER_SECRET) {
    // Loud, because a NEXT_PUBLIC_ prefix publishes the secret to every
    // browser that loads the app, and the app would still work — so nothing
    // else would ever reveal the mistake.
    throw new VideoConfigError(
      'NEXT_PUBLIC_ZEGOCLOUD_SERVER_SECRET is set. The server secret must ' +
        'never carry a NEXT_PUBLIC_ prefix: that publishes it to every ' +
        'browser. Remove it and use ZEGOCLOUD_SERVER_SECRET.',
    );
  }

  return { appId, secret };
}

function generateToken04({ appId, userId, secret, ttlSeconds, payload = '' }) {
  const ctime = Math.floor(Date.now() / 1000);
  const expire = ctime + ttlSeconds;

  const body = JSON.stringify({
    app_id: appId,
    user_id: userId,
    nonce: randomBytes(4).readInt32BE(0),
    ctime,
    expire,
    payload,
  });

  const iv = randomBytes(12);
  const cipher = createCipheriv('aes-256-gcm', Buffer.from(secret), iv);
  const encrypted = Buffer.concat([
    cipher.update(body, 'utf8'),
    cipher.final(),
    cipher.getAuthTag(),
  ]);

  const buffer = Buffer.alloc(8 + 2 + iv.length + 2 + encrypted.length + 1);
  let offset = 0;
  buffer.writeBigInt64BE(BigInt(expire), offset);
  offset += 8;
  buffer.writeUInt16BE(iv.length, offset);
  offset += 2;
  iv.copy(buffer, offset);
  offset += iv.length;
  buffer.writeUInt16BE(encrypted.length, offset);
  offset += 2;
  encrypted.copy(buffer, offset);
  offset += encrypted.length;
  buffer.writeUInt8(1, offset); // 1 = AES-GCM

  return `04${buffer.toString('base64')}`;
}

/**
 * Mint a token for one user in one room.
 *
 * The room id is passed in by the caller, but every caller in this codebase
 * derives it from a session the user has already been proved a participant of
 * (`roomIdFor` in `lib/sessions.js`). Nothing takes a room id from a request
 * body — that was the Phase 1 bug.
 */
export function mintSessionToken({ userId, roomId, ttlSeconds }) {
  const { appId, secret } = videoConfig();

  if (!/^[A-Za-z0-9_-]{1,64}$/.test(String(roomId))) {
    throw new VideoConfigError('Room id is not in the permitted form.');
  }

  const token = generateToken04({
    appId,
    userId,
    secret,
    ttlSeconds,
    // Scoping the token to one room is what stops a token minted for one
    // session being replayed into another.
    payload: JSON.stringify({ room_id: String(roomId) }),
  });

  return { token, appId, userId, roomId, ttlSeconds };
}

export const isVideoConfigured = () => {
  try {
    videoConfig();
    return true;
  } catch {
    return false;
  }
};
